import logo from "../assets/logo.jpg";
import { Link, useLocation } from "react-router-dom";

export default function Navbar() {
  const location = useLocation();

  const scrollToSection = (id) => {
    if (location.pathname !== "/") {
      window.location.href = `/#${id}`;
      return;
    }

    const section = document.getElementById(id);
    if (section) {
      section.scrollIntoView({ behavior: "smooth" });
    }
  };

  return (
    <nav className="fixed top-0 w-full z-50 h-20 bg-black/80 backdrop-blur border-b border-white/10">
      <div className="max-w-7xl mx-auto h-full flex items-center justify-between px-6">

        {/* LOGO */}
        <img
          src={logo}
          alt="Bodyzeal Fitworks"
          className="h-12 w-auto cursor-pointer"
          onClick={() => scrollToSection("top")}
        />

        {/* NAV LINKS */}
        <ul className="hidden md:flex gap-8 text-sm font-medium text-white">
          <li
            onClick={() => scrollToSection("programs")}
            className="hover:text-[#e9b21a] transition cursor-pointer"
          >
            Home
          </li>

          <li
            onClick={() => scrollToSection("membership")}
            className="hover:text-[#e9b21a] transition cursor-pointer"
          >
            Membership Plans
          </li>

          {/* ✅ GALLERY → SEPARATE PAGE */}
          <li className="hover:text-[#e9b21a] transition cursor-pointer">
            <Link to="/gallery">Gallery</Link>
          </li>

          <li
            onClick={() => scrollToSection("contact")}
            className="hover:text-[#e9b21a] transition cursor-pointer"
          >
            Contact
          </li>
        </ul>
      </div>
    </nav>
  );
}
